mapper.select:
WITH room_list AS ( SELECT m.room_id, m.room_name, m.type, m.location FROM meetingroom m WHERE m.status = 0 -- 只统计正常状态的会议室
AND m.type = #{query.roomType}
AND m.location = #{query.location}
),
usage_stats AS ( SELECT rl.room_id, rl.room_name, COUNT(r.reservation_id) as usage_count FROM room_list rl LEFT JOIN reservations r ON rl.room_id = r.room_id AND r.reserve_date BETWEEN CASE WHEN #{query.period} = 'week' THEN DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) WHEN #{query.period} = 'month' THEN DATE_FORMAT(CURDATE(), '%Y-%m-01') WHEN #{query.period} = 'quarter' THEN MAKEDATE(YEAR(CURDATE()), 1) + INTERVAL (QUARTER(CURDATE())-1)*3 MONTH - INTERVAL 1 DAY WHEN #{query.period} = 'year' THEN DATE_FORMAT(CURDATE(), '%Y-01-01') WHEN #{query.period} = 'custom' AND #{query.startDate} IS NOT NULL THEN #{query.startDate} ELSE DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) END AND CASE WHEN #{query.period} = 'week' THEN DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE())-6 DAY) WHEN #{query.period} = 'month' THEN LAST_DAY(CURDATE()) WHEN #{query.period} = 'quarter' THEN MAKEDATE(YEAR(CURDATE()), 1) + INTERVAL QUARTER(CURDATE())*3 MONTH - INTERVAL 1 DAY WHEN #{query.period} = 'year' THEN DATE_FORMAT(CURDATE(), '%Y-12-31') WHEN #{query.period} = 'custom' AND #{query.endDate} IS NOT NULL THEN #{query.endDate} ELSE DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE())-6 DAY) END AND r.status IN (2,4,3) -- 只统计已通过的预约 GROUP BY rl.room_id, rl.room_name ),
stat_summary AS ( SELECT COUNT(*) as room_count, SUM(usage_count) as total_usage, AVG(usage_count) as avg_usage, MAX(usage_count) as max_usage, MIN(usage_count) as min_usage FROM usage_stats ) SELECT
#{query.period} as period, DATE_FORMAT( CASE WHEN #{query.period} = 'week' THEN DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) WHEN #{query.period} = 'month' THEN DATE_FORMAT(CURDATE(), '%Y-%m-01') WHEN #{query.period} = 'quarter' THEN MAKEDATE(YEAR(CURDATE()), 1) + INTERVAL (QUARTER(CURDATE())-1)*3 MONTH - INTERVAL 1 DAY WHEN #{query.period} = 'year' THEN DATE_FORMAT(CURDATE(), '%Y-01-01') WHEN #{query.period} = 'custom' AND #{query.startDate} IS NOT NULL THEN #{query.startDate} ELSE DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) END, '%Y-%m-%d' ) as start_date, DATE_FORMAT( CASE WHEN #{query.period} = 'week' THEN DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE())-6 DAY) WHEN #{query.period} = 'month' THEN LAST_DAY(CURDATE()) WHEN #{query.period} = 'quarter' THEN MAKEDATE(YEAR(CURDATE()), 1) + INTERVAL QUARTER(CURDATE())*3 MONTH - INTERVAL 1 DAY WHEN #{query.period} = 'year' THEN DATE_FORMAT(CURDATE(), '%Y-12-31') WHEN #{query.period} = 'custom' AND #{query.endDate} IS NOT NULL THEN #{query.endDate} ELSE DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE())-6 DAY) END, '%Y-%m-%d' ) as end_date, NOW() as stat_time, ss.total_usage as total_usage_count, ss.avg_usage as average_usage_count, ss.max_usage as max_usage_count, ss.min_usage as min_usage_count FROM stat_summary ss

SELECT 0 as `rank`, m.room_id, m.room_name, COALESCE(COUNT(r.reservation_id), 0) as usage_count, m.type as room_type, m.capacity, m.location, ROUND( COALESCE(COUNT(r.reservation_id), 0) * 100.0 / NULLIF(( SELECT COUNT(*) FROM reservations WHERE reserve_date BETWEEN CASE WHEN #{query.period} = 'week' THEN DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) WHEN #{query.period} = 'month' THEN DATE_FORMAT(CURDATE(), '%Y-%m-01') WHEN #{query.period} = 'quarter' THEN MAKEDATE(YEAR(CURDATE()), 1) + INTERVAL (QUARTER(CURDATE())-1)*3 MONTH - INTERVAL 1 DAY WHEN #{query.period} = 'year' THEN DATE_FORMAT(CURDATE(), '%Y-01-01') WHEN #{query.period} = 'custom' AND #{query.startDate} IS NOT NULL THEN #{query.startDate} ELSE DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) END AND CASE WHEN #{query.period} = 'week' THEN DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE())-6 DAY) WHEN #{query.period} = 'month' THEN LAST_DAY(CURDATE()) WHEN #{query.period} = 'quarter' THEN MAKEDATE(YEAR(CURDATE()), 1) + INTERVAL QUARTER(CURDATE())*3 MONTH - INTERVAL 1 DAY WHEN #{query.period} = 'year' THEN DATE_FORMAT(CURDATE(), '%Y-12-31') WHEN #{query.period} = 'custom' AND #{query.endDate} IS NOT NULL THEN #{query.endDate} ELSE DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE())-6 DAY) END AND status IN (4,3,2) ), 0), 2 ) as usage_rate FROM meetingroom m LEFT JOIN reservations r ON m.room_id = r.room_id AND r.reserve_date BETWEEN CASE WHEN #{query.period} = 'week' THEN DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) WHEN #{query.period} = 'month' THEN DATE_FORMAT(CURDATE(), '%Y-%m-01') WHEN #{query.period} = 'quarter' THEN MAKEDATE(YEAR(CURDATE()), 1) + INTERVAL (QUARTER(CURDATE())-1)*3 MONTH - INTERVAL 1 DAY WHEN #{query.period} = 'year' THEN DATE_FORMAT(CURDATE(), '%Y-01-01') WHEN #{query.period} = 'custom' AND #{query.startDate} IS NOT NULL THEN #{query.startDate} ELSE DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE()) DAY) END AND CASE WHEN #{query.period} = 'week' THEN DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE())-6 DAY) WHEN #{query.period} = 'month' THEN LAST_DAY(CURDATE()) WHEN #{query.period} = 'quarter' THEN MAKEDATE(YEAR(CURDATE()), 1) + INTERVAL QUARTER(CURDATE())*3 MONTH - INTERVAL 1 DAY WHEN #{query.period} = 'year' THEN DATE_FORMAT(CURDATE(), '%Y-12-31') WHEN #{query.period} = 'custom' AND #{query.endDate} IS NOT NULL THEN #{query.endDate} ELSE DATE_SUB(CURDATE(), INTERVAL WEEKDAY(CURDATE())-6 DAY) END AND r.status IN (4,3,2) WHERE m.status = 0
AND m.type = #{query.roomType}
AND m.location = #{query.location}
AND r.reservation_id IS NOT NULL
GROUP BY m.room_id, m.room_name, m.type, m.capacity, m.location ORDER BY
usage_count DESC usage_count ASC m.room_name usage_count DESC
LIMIT #{query.limit}

SELECT room_id, room_name, type, location, capacity FROM meetingroom WHERE status = 0
AND type = #{roomType}
AND location = #{location}
ORDER BY room_name
